 home.parent.mkdir(parents=True);home.write_text(t.rstrip()+'\n');manifest.append({'source_id':sid,'path':str(home),'sha256':sha(home.read_bytes()),'copies':copies,'read_scope':row['scope'],'cards':len(row['cards']),'original_url':row['url'],'law_anchor':row['anchor']})
